let state={clients:[],customPrograms:[],customExercises:[],sessions:[],cycles:[],history:[],metrics:{},checkins:[],preferences:{variability:'balanced'}};
function migrateState(){
  let raw=localStorage.getItem(STORAGE);
  if(raw){try{return JSON.parse(raw)}catch(_){}}
  for(const k of Object.keys(localStorage)){
    if(k===STORAGE||!/fafatraining/i.test(k))continue;
    try{const v=JSON.parse(localStorage.getItem(k));if(v&&typeof v==='object'&&(v.clients||v.adhérents||v.sessions||v.cycles)){localStorage.setItem(STORAGE,JSON.stringify(v));return v}}catch(_){ }
  }
  return null;
}
