function safePortalItem(it={}){return{id:it.id||null,name:it.variantExercise||it.name||'Exercice',variantExercise:it.variantExercise||it.name||'Exercice',variantExerciseId:it.variantExerciseId||it.id||null,sets:it.sets||'3',reps:it.reps||'10',rest:it.rest||'60 s',tempo:it.tempo||'contrôlé',intensity:it.intensity||'RPE 6–8',cue:it.cue||it.cues||'',fafaTip:it.fafaTip||'',type:it.type||'exercise',demoPattern:it.demoPattern||'general'}}
