function safePortalProgram(p){return{id:p.id,title:p.title||'Programme FAFATRAINING',objective:p.objective||'',duration:p.duration||45,frequency:p.frequency||2,bodyZone:p.bodyZone||'Corps entier',intensity:p.intensity||'standard',blocks:safePortalBlocks(p.blocks||[])}}
