function portalAccessModal(c){const programs=state.customPrograms.filter(p=>p.clientId===c.id),active=state.accesses.filter(a=>a.clientId===c.id&&+a.expiresAt>Date.now()).sort((a,b)=>+b.expiresAt-+a.expiresAt)[0];return modal(`<span class="eyebrow">PORTAIL ADHÉRENT</span><h2>Donner un accès à ${esc(clientName(c))}</h2><p class="modal-note">Le portail ne contient que son programme, ses séances planifiées et ses propres résultats locaux. Aucune note coach ni donnée d’un autre adhérent n’est incluse.</p>${active?`<div class="portal-status"><b>Accès actuel</b><span>Valable jusqu’au ${esc(new Date(+active.expiresAt).toLocaleString('fr-FR'))}</span></div>`:''}<form id="portal-access-form" class="form-grid"><input type="hidden" name="clientId" value="${esc(c.id)}"><div class="field"><label>Durée d’accès</label><select name="days"><option value="7">7 jours</option><option value="14">14 jours</option><option value="30" selected>30 jours</option><option value="60">60 jours</option><option value="90">90 jours</option></select></div><div class="field"><label>Inclure le planning</label><select name="includePlanning"><option value="yes" selected>Oui</option><option value="no">Non</option></select></div><div class="field full"><label>Programme(s) accessible(s)</label><div class="choice-grid" data-choice="portalPrograms">${programs.map((p,i)=>`<button type="button" data-value="${esc(p.id)}" class="${i===programs.length-1?'on':''}">${esc(p.title)}</button>`).join('')||'<span class="muted-inline">Crée d’abord un programme personnalisé pour cet adhérent.</span>'}</div></div><div class="field full"><div class="portal-note"><b>GitHub Pages</b><span>L’accès expire automatiquement dans l’application à la date prévue. Sans backend, il n’existe pas de révocation serveur instantanée : génère un nouveau lien si tu modifies l’accompagnement.</span></div></div><div class="field full actions"><button class="btn primary" type="submit" ${programs.length?'':'disabled'}>Générer l’accès</button><button class="btn secondary" type="button" data-action="close-modal">Annuler</button></div></form>`,true)}
function portalResultModal(){const x=ui.portalShare;if(!x)return modal('<div class="empty"><strong>Aucun accès généré</strong></div>');return modal(`<span class="eyebrow">ACCÈS CRÉÉ</span><h2>${esc(x.clientName)}</h2><div class="portal-access-card"><span>Valable jusqu’au</span><b>${esc(new Date(x.expiresAt).toLocaleString('fr-FR'))}</b><small>${x.days} jours · ${x.programCount} programme${x.programCount>1?'s':''}</small></div><div class="field"><label>Lien d’accès recommandé</label><textarea readonly rows="4">${esc(x.link)}</textarea></div><div class="field"><label>Code d’accès</label><textarea readonly rows="5">${esc(x.token)}</textarea></div><div class="actions"><button class="btn primary" data-action="copy-portal-link">Copier le lien</button><button class="btn secondary" data-action="copy-portal-code">Copier le code</button><button class="btn secondary" data-action="preview-portal">Tester le portail</button></div><p class="modal-note">Le lien transporte uniquement les données nécessaires à cet adhérent. Il ne donne jamais accès au Coach Studio, aux autres adhérents ni à la bibliothèque privée du coach.</p>`,true)}
async function buildPortalAccess(client,days,programIds,includePlanning=true){const now=Date.now(),expiresAt=now+days*86400000,programs=state.customPrograms.filter(p=>p.clientId===client.id&&programIds.includes(p.id)).map(safePortalProgram),sessions=includePlanning?state.sessions.filter(x=>x.clientId===client.id&&(!x.scheduledAt||(+new Date(x.scheduledAt)>=now-86400000&&+new Date(x.scheduledAt)<=expiresAt))).map(safePortalSession):[];const payload={v:1,accessId:uid('access'),clientId:client.id,issuedAt:now,expiresAt,client:{firstName:client.firstName||'Adhérent',goal:client.goal||'',sessionsPerWeek:client.sessionsPerWeek||2},programs,sessions};const token=await createPortalToken(payload);return{payload,token}}
function portalReportImportModal(clientId){return modal(`<span class="eyebrow">BILAN ADHÉRENT</span><h2>Importer les séances réalisées</h2><p class="modal-note">L’adhérent copie son « code bilan » depuis son portail. Colle-le ici pour intégrer ses séances à l’historique coach.</p><form id="portal-report-form" class="form-grid"><input type="hidden" name="clientId" value="${esc(clientId)}"><div class="field full"><label>Code bilan</label><textarea name="report" rows="8" required placeholder="FAR1.…"></textarea></div><div class="field full actions"><button class="btn primary" type="submit">Importer le bilan</button><button class="btn secondary" type="button" data-action="close-modal">Annuler</button></div></form>`,true)}
