 const cards=state.clients.length?`<div class="client-grid">${state.clients.map(c=>{const ci=getTodayCheckin(c.id);return `<article class="client-card"><div class="client-avatar">${esc(clientInitials(c))}</div><div>${ci?`<span class="readiness">Aujourd’hui · énergie ${esc(ci.energy)}/5</span>`:''}<h3>${esc(clientName(c))}</h3><p>${esc(c.goal||'Objectif à définir')} · ${esc(c.sessionsPerWeek||2)}×/sem · ${esc(c.sessionDuration||45)} min</p></div><div class="card-actions"><button class="btn primary small" data-go="client:${c.id}">Ouvrir la fiche</button><button class="btn secondary small" data-action="client-checkin" data-id="${c.id}">Check-in</button><button class="btn secondary small" data-action="personalize-from-client" data-id="${c.id}">Créer son programme</button></div></article>`}).join('')}</div>`:`<div class="empty"><strong>Commence par créer un adhérent</strong><span>Le profil devient la base de la personnalisation et du suivi.</span><div class="actions" style="justify-content:center;margin-top:14px"><button class="btn primary" data-action="new-client">${icon('plus')} Créer la première fiche</button></div></div>`;
