 if(a==='portal-start-program'){ui.portalModal=portalWorkoutModal('program',id);renderPortal();return}
 if(a==='portal-start-session'){ui.portalModal=portalWorkoutModal('session',id);renderPortal();return}
 if(a==='portal-exercise-info'){ui.portalModal=portalExerciseInfo(el.dataset.kind,el.dataset.source,+el.dataset.ei);renderPortal();return}
 if(a==='portal-copy-report'){const logs=ui.portalLocal?.logs||[];if(!logs.length)return;const code=encodeReport({v:1,accessId:ui.portalAccess.accessId,clientId:ui.portalAccess.clientId,clientName:ui.portalAccess.client?.firstName||'Adhérent',exportedAt:Date.now(),logs});await copyText(code);toast('Bilan copié · envoie-le à ton coach');return}
 if(a==='portal-access'){const c=state.clients.find(x=>x.id===id);if(c){ui.modal=portalAccessModal(c);render()}return}
 if(a==='import-portal-report'){ui.modal=portalReportImportModal(id);render();return}
 if(a==='copy-portal-link'){if(ui.portalShare){await copyText(ui.portalShare.link);toast('Lien adhérent copié')}return}
