 if(a==='toggle-muscle'){const m=el.dataset.muscle;ui.selectedMuscles.includes(m)?ui.selectedMuscles=ui.selectedMuscles.filter(x=>x!==m):ui.selectedMuscles.push(m);render();return}
 if(a==='clear-muscles'){ui.selectedMuscles=[];render();return}
 if(a==='search-selected-muscles'){ui.movementFilters.muscle=ui.selectedMuscles[0]||'Tous';ui.movementFilters.q=ui.selectedMuscles.slice(1).join(' ');ui.movementLimit=72;go('movements');return}
 if(a==='programs-selected-muscles'){ui.programFilters.zone=ui.selectedMuscles[0]||'Toutes';ui.programFilters.q='';go('programs');return}
 if(a==='blank-program'||a==='blank-program-for-client'){ui.editDraft={id:'custom_'+uid('program'),title:'Mon programme FAFATRAINING',clientId:a==='blank-program-for-client'?id:'',objective:'Objectif personnalisé',duration:45,frequency:2,bodyZone:'Corps entier',category:'Personnalisé',family:'Personnalisé',equipmentClass:'Adaptable',intensity:'standard',variability:'balanced',blocks:[{label:'Bloc principal',instruction:'',items:[]}],custom:true,createdAt:new Date().toISOString()};setEditorModal();return}
 if(a==='open-program'){await openProgram(id);return}
 if(a==='program-base'){ui.programBaseId=id;ui.modal=renderProgramModal(ui.programGroup,id,ui.intensity);render();return}
 if(a==='program-setup'){ui.programSetup=el.dataset.value;ui.programGoal='Tous';const candidates=ui.programGroup.programs.filter(x=>(x.equipmentClass||'Adaptable')===ui.programSetup);ui.programBaseId=candidates[0]?.id||ui.programBaseId;ui.modal=renderProgramModal(ui.programGroup,ui.programBaseId,ui.intensity);render();return}
 if(a==='program-goal'){ui.programGoal=el.dataset.value;const candidates=ui.programGroup.programs.filter(x=>(x.equipmentClass||'Adaptable')===ui.programSetup&&(x.objective||'Objectif')===ui.programGoal);ui.programBaseId=candidates[0]?.id||ui.programBaseId;ui.modal=renderProgramModal(ui.programGroup,ui.programBaseId,ui.intensity);render();return}
 if(a==='program-intensity'){ui.intensity=el.dataset.value;ui.modal=renderProgramModal(ui.programGroup,ui.programBaseId,ui.intensity);render();return}
 if(a==='program-variability'){ui.variability=el.dataset.value;state.preferences.variability=ui.variability;save();ui.modal=renderProgramModal(ui.programGroup,ui.programBaseId,ui.intensity);render();return}
 if(a==='use-program'){ui.modal=useProgramModal(getProgram(id));render();return}
 if(a==='personalize-program'){ui.modal=personalizeSelectModal(id,el.dataset.client||'');render();return}
 if(a==='confirm-personalize'){await window.FTCatalog?.ensureProgram(el.dataset.program);const p=getProgram(el.dataset.program),c=state.clients.find(x=>x.id===el.dataset.client);if(p&&c){const chosen=el.dataset.intensity||ui.intensity||c.intensityPreference||'standard';const cp=personalizeProgram(p,c,chosen,c.variability||ui.variability);state.customPrograms.push(cp);save();ui.modal=null;toast(`Programme créé pour ${clientName(c)}`);go('client:'+c.id)}return}
 if(a==='edit-program-copy'){ui.editDraft=programToDraft(getProgram(id),ui.intensity);setEditorModal();return}
