 if(a==='delete-custom-program'){if(confirm('Supprimer ce programme personnalisé ?')){state.customPrograms=state.customPrograms.filter(p=>p.id!==id);save();ui.modal=null;render();toast('Programme supprimé')}return}
 if(a==='schedule-custom-program'){const p=getProgram(id);ui.modal=modal(`<span class="eyebrow">PLANIFIER</span><h2>${esc(p?.title||'Programme')}</h2>${sessionForm({programId:id,title:p?.title||'Séance'},p?.clientId||'')}`);render();return}
 if(a==='start-custom-now'){const p=getProgram(id);if(p){const s=sessionFromProgram(p,p.clientId||'');state.sessions.push(s);save();maybeStartSession(s.id)}return}
