 if(a==='edit-session'){const s=state.sessions.find(x=>x.id===id);ui.modal=modal(`<span class="eyebrow">MODIFIER LE RENDEZ-VOUS</span><h2>${esc(s?.title||'Séance')}</h2>${sessionForm(s||{})}`);render();return}
 if(a==='start-session'){maybeStartSession(id);return}
 if(a==='open-cycles'){ui.modal=cyclesModal();render();return}
 if(a==='new-cycle'){ui.modal=modal(`<span class="eyebrow">NOUVEAU CYCLE</span><h2>Programmer plusieurs semaines</h2>${cycleForm()}`);render();return}
 if(a==='advance-cycle'){const c=state.cycles.find(x=>x.id===id);if(c){const max=+c.weeks||4;if((+c.currentWeek||1)<max)c.currentWeek=(+c.currentWeek||1)+1;else c.completed=true;save();ui.modal=cyclesModal();render()}return}
 if(a==='edit-cycle-week'){const c=state.cycles.find(x=>x.id===id);if(c){ui.modal=cycleWeekModal(c,+el.dataset.week);render()}return}
 if(a==='delete-cycle'){if(confirm('Supprimer ce cycle ?')){state.cycles=state.cycles.filter(c=>c.id!==id);save();ui.modal=cyclesModal();render()}return}
 if(a==='open-timer'){ui.timer=ui.timer||{seconds:60,initial:60,running:false,end:null};ui.modal=timerModal();render();return}
 if(a==='timer-set'){ui.timer={seconds:+el.dataset.value,initial:+el.dataset.value,running:false,end:null};ui.modal=timerModal();render();return}
 if(a==='timer-toggle'){if(!ui.timer)ui.timer={seconds:60,initial:60,running:false};if(ui.timer.running){ui.timer.seconds=Math.max(0,Math.ceil((ui.timer.end-Date.now())/1000));ui.timer.running=false;ui.timer.end=null}else{ui.timer.running=true;ui.timer.end=Date.now()+ui.timer.seconds*1000}ui.modal=timerModal();render();return}
 if(a==='timer-reset'){ui.timer={seconds:ui.timer?.initial||60,initial:ui.timer?.initial||60,running:false,end:null};ui.modal=timerModal();render();return}
