 if(a==='export-backup'){downloadBlob(new Blob([JSON.stringify({app:'FAFATRAINING',exportedAt:new Date().toISOString(),state},null,2)],{type:'application/json'}),'FAFATRAINING-sauvegarde.json');toast('Sauvegarde exportée');return}
 if(a==='import-backup'){$('#import-file')?.click();return}
 if(a==='add-metric'){ui.modal=metricModal(id);render();return}
 if(a==='editor-add-block'){syncEditorDraft();ui.editDraft.blocks.push({label:'Nouveau bloc',instruction:'',items:[]});setEditorModal();return}
 if(a==='editor-add-exercise'){syncEditorDraft();ui.modal=replacementModal({type:'editorAdd',bi:+el.dataset.bi});render();return}
 if(a==='editor-replace'){syncEditorDraft();ui.modal=replacementModal({type:'editor',bi:+el.dataset.bi,ii:+el.dataset.ii});render();return}
 if(a==='editor-up'||a==='editor-down'||a==='editor-delete'){syncEditorDraft();const bi=+el.dataset.bi,ii=+el.dataset.ii,arr=ui.editDraft.blocks[bi].items;if(a==='editor-delete')arr.splice(ii,1);else{const ni=a==='editor-up'?ii-1:ii+1;if(ni>=0&&ni<arr.length)[arr[ii],arr[ni]]=[arr[ni],arr[ii]]}setEditorModal();return}
 if(a==='choose-replacement'){let ctx={};try{ctx=JSON.parse(el.dataset.context||'{}')}catch(_){ }const e=getExercise(id);if(!e)return;if(ctx.type==='editor'){ui.editDraft.blocks[ctx.bi].items[ctx.ii]={...ui.editDraft.blocks[ctx.bi].items[ctx.ii],...makeItem(e)};setEditorModal()}else if(ctx.type==='editorAdd'){ui.editDraft.blocks[ctx.bi].items.push(makeItem(e));setEditorModal()}else if(ctx.type==='live'){const s=state.sessions.find(x=>x.id===ui.live.sessionId),it=flattenSession(s)[ui.live.index];if(it){s.blocks[it._bi].items[it._ii]={...s.blocks[it._bi].items[it._ii],...makeItem(e)};save();restoreLive()}}return}
 if(a==='save-editor'){syncEditorDraft();if(!ui.editDraft.title.trim()){toast('Ajoute un titre');return}const idx=state.customPrograms.findIndex(p=>p.id===ui.editDraft.id);if(idx>=0)state.customPrograms[idx]=clone(ui.editDraft);else state.customPrograms.push(clone(ui.editDraft));save();const saved=ui.editDraft;ui.modal=customProgramModal(saved);render();toast('Programme enregistré');return}
 if(a==='add-exercise-to-blank'){const e=getExercise(id);ui.editDraft={id:'custom_'+uid('program'),title:`Programme autour de ${e.name}`,clientId:'',objective:'Objectif personnalisé',duration:45,frequency:2,bodyZone:e.bodyZone||'Corps entier',category:'Personnalisé',family:'Personnalisé',equipmentClass:'Adaptable',intensity:'standard',variability:'balanced',blocks:[{label:'Bloc principal',items:[makeItem(e)]}],custom:true,createdAt:new Date().toISOString()};setEditorModal();return}
 if(a==='live-complete'){captureLiveInputs();const note=$('#live-note');if(note)ui.live.notes[ui.live.index]=note.value;const s=state.sessions.find(x=>x.id===ui.live.sessionId),n=flattenSession(s).length;if(ui.live.index<n-1){ui.live.index++;ui.modal=liveModal();render()}else finishLive();return}
 if(a==='live-skip'){captureLiveInputs();ui.live.skipped.push(ui.live.index);const s=state.sessions.find(x=>x.id===ui.live.sessionId),n=flattenSession(s).length;if(ui.live.index<n-1){ui.live.index++;ui.modal=liveModal();render()}else finishLive();return}
